"""Install pinned native cohort helpers only; never start a workload or SDK."""
import argparse,base64,hashlib,json,os,socket,zlib
from pathlib import Path

FILES={'four_runtime.py': {'sha256': 'a7c538b417e350177547ba3442d8e177a3234c888da6a48c69f563f9db5b89b4', 'bytes': 12743, 'data': ''}, 'cohort_engine.py': {'sha256': 'fbd1279eb5ae38c90d9ebed36e80d362f16da0ee1e5867288c2f3f9959a24336', 'bytes': 20047, 'data': ''}, 'four_lifecycle.py': {'sha256': 'e5f8f77dc441063724077d2aef22733742c477b477473b86b22f916960857f41', 'bytes': 6158, 'data': ''}, 'ram_observer.py': {'sha256': '2aeeb8e9b4b875972bf8d6a41e98344c6709b7ccce472e25003b9ff09d16e112', 'bytes': 19092, 'data': ''}, 'four_replay.py': {'sha256': '780779b6d3f2c6ea2b7c4a6115d193b9d4116b654251149bac1cc5e0d004d20e', 'bytes': 1915, 'data': ''}, 'four_sync.py': {'sha256': '2f2bb5782022d483c5eed9969ef7358e48587805f4d8023869d7b7660aa21ced', 'bytes': 9387, 'data': ''}, 'four_metrics.py': {'sha256': 'd1a3e80825db2f62234a6b81f8141a9442b34cf6de10680ddb4b933d8c728a20', 'bytes': 6642, 'data': ''}, 'host_metrics.py': {'sha256': '0d98546e829d1d547b1cceb101c455812d684b832441f5db775b50258dd5eed6', 'bytes': 4565, 'data': ''}, 'native_snapshot_transport.py': {'sha256': '4ad84394400e193128a140d07116f7ad57d08eb4a8ee635383027ab049854d79', 'bytes': 19941, 'data': ''}, 'native_archive_cohort.py': {'sha256': '6f49ca8f48b4ab98f72ca6ddfa04a0c35eccdbd6694b388531b32d53c706bb7f', 'bytes': 28862, 'data': ''}}
ROOT=Path('/home/jwk/agent')
DEST=ROOT/'native-archive-cohort'

def need(ok,reason):
    if not ok:raise RuntimeError(reason)

def decoded(name):
    row=FILES[name];data=zlib.decompress(base64.b64decode(row['data'],validate=True))
    need(len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256'],'Pinned cohort payload differs')
    return data

def stage(destination):
    need(destination.is_absolute() and destination.resolve()==destination and destination.parent.is_dir()
         and not destination.exists() and not destination.is_symlink(),'Existing or redirected helper installation preserved')
    values={name:decoded(name) for name in FILES}
    need(set(values)=={'cohort_engine.py','four_lifecycle.py','four_metrics.py','four_replay.py','four_runtime.py',
         'four_sync.py','host_metrics.py','native_archive_cohort.py','native_snapshot_transport.py','ram_observer.py'},'Unexpected helper inventory')
    destination.mkdir(mode=0o777 if os.name=='nt' else 0o700)
    for name,data in values.items():
        with (destination/name).open('xb') as output:output.write(data);output.flush();os.fsync(output.fileno())
    report={'status':'NATIVE_COHORT_HELPERS_INSTALLED_NOT_RUN','files':{n:FILES[n]['sha256'] for n in FILES},
            'entry':str(destination/'native_archive_cohort.py'),'SDK_called':False,'Guest_created':False,'servicesChanged':False}
    with (destination/'installation.json').open('x') as output:json.dump(report,output,indent=2)
    return report

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--install',action='store_true');a=p.parse_args()
    if not a.install:print('PLAN_ONLY_NO_INSTALL_SDK_OR_GUEST');return 0
    need(os.name=='posix' and os.getuid()==os.geteuid()==1204 and socket.gethostname() in ('server1','agent1'),
         'Use the ordinary experiment user on the intended node')
    need(ROOT.resolve(strict=True)==ROOT and ROOT.stat().st_uid==1204,'Installation workspace differs')
    os.umask(0o077);print(json.dumps(stage(DEST),indent=2));return 0

if __name__=='__main__':raise SystemExit(main())
